 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8" />
   <meta name="viewport" content="width=device-width, initial-scale=1.0" />
   <title>Terms Consent Form</title>
   <style>
     :root {
       color-scheme: dark;
       --bg: #0f1115;
       --panel: #171a21;
       --panel-2: #1d212a;
       --text: #e8ebf2;
       --muted: #a7afc0;
       --border: #2b3140;
       --accent: #7c9cff;
       --accent-strong: #9db2ff;
       --focus: rgba(124, 156, 255, 0.35);
       --shadow: 0 24px 60px rgba(0, 0, 0, 0.45);
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       display: grid;
       place-items: center;
       padding: 24px;
       font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       background:
         radial-gradient(circle at top, rgba(124, 156, 255, 0.15), transparent 32%),
         linear-gradient(180deg, #11141a 0%, #0c0e12 100%);
       color: var(--text);
     }

     .card {
       width: min(100%, 440px);
       background: linear-gradient(180deg, var(--panel) 0%, #131720 100%);
       border: 1px solid var(--border);
       border-radius: 20px;
       box-shadow: var(--shadow);
       padding: 28px;
     }

     h1 {
       margin: 0 0 10px;
       font-size: 1.5rem;
       line-height: 1.2;
     }

     p {
       margin: 0;
       color: var(--muted);
       line-height: 1.6;
     }

     form {
       margin-top: 24px;
       display: grid;
       gap: 18px;
     }

     .form-field {
       padding: 18px;
       background: var(--panel-2);
       border: 1px solid var(--border);
       border-radius: 16px;
       transition: border-color 0.2s ease, box-shadow 0.2s ease;
     }

     .form-field:focus-within {
       border-color: var(--accent);
       box-shadow: 0 0 0 4px var(--focus);
     }

     .checkbox-row {
       display: flex;
       gap: 12px;
       align-items: flex-start;
     }

     input[type="checkbox"] {
       width: 20px;
       height: 20px;
       margin: 2px 0 0;
       accent-color: var(--accent);
       flex: 0 0 auto;
     }

     label {
       display: grid;
       gap: 4px;
       cursor: pointer;
     }

     .label-text {
       font-weight: 600;
       color: var(--text);
     }

     .helper-text {
       font-size: 0.95rem;
       color: var(--muted);
       line-height: 1.5;
     }

     button {
       appearance: none;
       border: 0;
       border-radius: 999px;
       padding: 14px 18px;
       background: linear-gradient(180deg, var(--accent) 0%, #5f7ef7 100%);
       color: #fff;
       font: inherit;
       font-weight: 700;
       cursor: pointer;
       box-shadow: 0 10px 24px rgba(124, 156, 255, 0.25);
       transition: transform 0.15s ease, filter 0.15s ease;
     }

     button:hover {
       filter: brightness(1.05);
     }

     button:active {
       transform: translateY(1px);
     }

     button:focus-visible,
     input:focus-visible {
       outline: 3px solid var(--accent-strong);
       outline-offset: 3px;
     }

     .status {
       min-height: 1.25rem;
       color: var(--accent-strong);
       font-size: 0.95rem;
     }
   </style>
 </head>
 <body>
   <main class="card">
     <h1>Consent to Terms</h1>
     <p>Please confirm your agreement before submitting the form.</p>

     <form id="consent-form" novalidate>
       <div class="form-field">
         <div class="checkbox-row">
           <input
             type="checkbox"
             id="terms"
             name="terms"
             required
             aria-describedby="terms-help"
           />
           <label for="terms">
             <span class="label-text">I agree to the Terms of Use</span>
             <span class="helper-text" id="terms-help">This is required to continue.</span>
           </label>
         </div>
       </div>

       <button type="submit">Submit</button>
       <div class="status" id="status" aria-live="polite"></div>
     </form>
   </main>

   <script>
     const form = document.getElementById('consent-form');
     const checkbox = document.getElementById('terms');
     const status = document.getElementById('status');

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       if (!checkbox.checked) {
         status.textContent = 'Please agree to the Terms of Use to continue.';
         checkbox.focus();
         return;
       }

       status.textContent = 'Consent submitted.';
       form.reset();
     });
   </script>
 </body>
 </html>

